WITH filtered AS (SELECT id, store_name, region, opened_date, sqft, CONCAT_WS('-', store_name, region) AS store_name_region_key, COALESCE(region, 'DIRECT') AS resolved_region FROM stores WHERE region IN ('East', 'South', 'Central')) SELECT id, store_name, opened_date, store_name_region_key, resolved_region, LEAD(sqft, 1, 0) OVER (ORDER BY sqft, id) AS next_sqft, FIRST_VALUE(sqft) IGNORE NULLS OVER (ORDER BY sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_sqft, SUM(sqft) OVER (ORDER BY sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_sqft FROM filtered;
